#include <queue>
#include <iostream>

void process_queue(std::queue<int>& q) {
    if (q.empty()) {
        // Correct handling
        std::cerr << "Queue is empty.\n";
        return;
    }

    // Safe access
    std::cout << "Front: " << q.front() << "\n";
    q.pop();

    // DANGER: UB if q was empty and we didn't check
    // int x = q.front(); 
}
